45|{% if view.diagnosis %}<p>Category: <strong>{{ view.diagnosis.category }}</strong></p>{% endif %}
46|
47|{% if view.handoff %}
48|<h2>Handoff</h2>
49|<p>Reason: {{ view.handoff.reason }}</p>
50|<p>Paused at: {{ view.handoff.paused_at }}, model calls since pause: {{ view.handoff.model_calls_since_pause }}</p>
51|{% if view.handoff.escalation_summary %}<p>Escalation: {{ view.handoff.escalation_summary }}</p>{% endif %}
52|{% if view.handoff.last_refusal %}<p>Last refusal: turn {{ view.handoff.last_refusal.n }} {{ view.handoff.last_refusal.tool }}</p>{% endif %}
