54|<div class="controls">
55|<h3>Operator controls</h3>
56|<div>
57|<input id="reply-msg" placeholder="Reply message">
58|<input id="reply-turns" type="number" value="0" min="0" style="width:4rem">
59|<button id="btn-reply">Reply</button>
60|</div>
61|<div>
62|<input id="grant-turns" type="number" value="4" min="1" max="24" style="width:4rem">
63|<button id="btn-grant">Grant turns</button>
64|</div>
65|<div>
66|<input id="close-note" placeholder="Close note">
67|<button id="btn-close">Close</button>
68|</div>
69|{% if rotatable %}
70|<div>
71|<button data-clear-url="/api/demo/faults/{{ rotatable[0].id }}/clear">Mark rotated ({{ rotatable[0].id }})</button>
72|</div>
73|{% endif %}
74|</div>
75|{% endif %}
76|{% endif %}
