79|{% for h in view.hypotheses %}
80|<section>
81|<h3>{{ h.id }}: {{ h.statement }}</h3>
82|<p>Would confirm: {{ h.wouldConfirm }}{% if h.alternative %} (alternative){% endif %}</p>
83|<ul>
84|{% for e in view.evidence if e.hypothesis == h.id %}
85|<li>{{ e.id }} ({{ e.stance }}, turn {{ e.recordedAtTurn }}): {{ e.why }} &mdash; {{ e.source.kind }}{% if e.source.kind == "log" %} {{ e.source.insertId }} {{ e.source.severity }}{% else %} {{ e.source.tool }} {{ e.source.field }}={{ e.source.value }}{% endif %}</li>
86|{% endfor %}
87|</ul>
88|</section>
89|{% endfor %}
90|
91|<h2>Proposal</h2>
92|{% if view.proposal %}
93|<p>{{ view.proposal.method }} {{ view.proposal.resource }} (seq {{ view.proposal.seq }}, {{ view.proposal.hash }})</p>
94|{% if view.proposal.diff %}
95|<table class="diff">
96|<thead><tr><th>Field</th><th>Before</th><th>After</th></tr></thead>
97|<tbody>
98|{% for row in view.proposal.diff %}
99|<tr><td>{{ row.field }}</td><td>{{ row.before }}</td><td>{{ row.after }}</td></tr>
100|{% endfor %}
101|</tbody>
102|</table>
103|{% else %}
104|<p>{{ view.proposal.steps }}</p>
105|{% endif %}
106|{% else %}
107|<p>No proposal.</p>
108|{% endif %}
