110|{% if admin and view.state == "AWAITING_APPROVAL" and view.proposal %}
111|<div class="controls">
112|<h3>Approval</h3>
113|<button id="btn-approve">Approve {{ view.proposal.hash }}</button>
114|<div>
115|<input id="reject-notes" placeholder="Rejection notes" style="width:24rem">
116|<button id="btn-reject">Reject</button>
117|</div>
118|</div>
119|{% endif %}
