122|{% if view.verification %}
123|<p>{{ view.verification.tripwire }}: {{ view.verification.current }}, {{ view.verification.outcome }} (started {{ view.verification.started_at }}, deadline {{ view.verification.deadline }})</p>
124|{% else %}
125|<p>No verification.</p>
126|{% endif %}
