import sys
sys.path.insert(0, "tests/acceptance/d8")
from d8_helpers import make_host, drive, ADMIN_HEADERS, make_client
from fleetsre.control.incidents import IncidentState

# F2 after clear_fault then RESOLVED
host=make_host("F2")
rt=host.current
rec=drive(rt,IncidentState.NEEDS_INPUT)
print("F2 paused", rec.paused_at)
faults=rt.active_faults()
print("faults", faults)
rt.clear_fault(faults[0]["id"])
rec2=rt.manager.get(rt.act.incident)
print("after clear timeline:")
for ev in rec2.timeline:
    print(f"  {ev.at.isoformat()} {ev.kind} {ev.detail}")
print("state", rec2.state)
# drive to resolved
rec3=drive(rt,IncidentState.RESOLVED)
print("=== F2 RESOLVED ===")
for ev in rec3.timeline:
    print(f"  {ev.at.isoformat()} {ev.kind} {ev.detail}")
print("diagnosis", rec3.diagnosis)
print("postmortem", rec3.postmortem.model_dump(mode="json") if rec3.postmortem else None)

# F3 reject + approve + resolved
print("\n\n=== F3 reject flow ===")
host3=make_host("F3")
rt3=host3.current
client3=make_client(host3)
rec=drive(rt3,IncidentState.AWAITING_APPROVAL)
h=rec.proposals[-1].hash
client3.post(f"/api/incidents/{rt3.act.incident}/reject", json={"proposal_hash":h,"notes":"unknown severities should map to 100"}, headers=ADMIN_HEADERS)
rec=rt3.manager.get(rt3.act.incident)
print("after reject", rec.state, rec.pending)
for ev in rec.timeline:
    print(f"  {ev.at.isoformat()} {ev.kind} {ev.detail}")
rt3.advance(rt3.act.tick_seconds)
rec=rt3.manager.get(rt3.act.incident)
print("after tick", rec.state)
for ev in rec.timeline:
    print(f"  {ev.at.isoformat()} {ev.kind} {ev.detail}")
print("proposals", [(p.seq,p.method,p.diagnosis.get("summary")) for p in rec.proposals])
# approve
h2=rec.proposals[-1].hash
client3.post(f"/api/incidents/{rt3.act.incident}/approve", json={"proposal_hash":h2}, headers=ADMIN_HEADERS)
rec=drive(rt3,IncidentState.RESOLVED)
print("=== F3 RESOLVED ===")
for ev in rec.timeline:
    print(f"  {ev.at.isoformat()} {ev.kind} {ev.detail}")
print("postmortem", rec.postmortem.model_dump(mode="json") if rec.postmortem else None)

# F1 resolved
print("\n\n=== F1 resolved ===")
host1=make_host("F1")
